package servicio;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.math.BigDecimal;import java.time.*;import org.junit.jupiter.api.Test;import dao.OrdenPagoDAO;import negocio.*;
class ConsultaOrdenPagoOnlineServiceTest {private OrdenPago orden(String url,LocalDateTime vence){OrdenPago o=new OrdenPago();o.setId(1);o.setReservaId(2);o.setProveedor(ProveedorPago.MERCADO_PAGO);o.setMetodo(MetodoOrdenPago.PAGO_ONLINE);o.setEstado(EstadoOrdenPago.ESPERANDO_PAGO);o.setImporte(new BigDecimal("6250"));o.setFechaExpiracion(vence);o.setUrlPago(url);return o;}@Test void exponeCheckoutHttpsVigente(){Clock c=Clock.fixed(Instant.parse("2026-10-14T10:00:00Z"),ZoneOffset.UTC);var s=new ConsultaOrdenPagoClienteService(mock(OrdenPagoDAO.class),c);assertEquals("https://www.mercadopago.com/checkout",s.convertir(orden("https://www.mercadopago.com/checkout",LocalDateTime.of(2026,10,14,10,10))).checkoutUrl());}@Test void ocultaCheckoutInseguroOVencido(){Clock c=Clock.fixed(Instant.parse("2026-10-14T10:00:00Z"),ZoneOffset.UTC);var s=new ConsultaOrdenPagoClienteService(mock(OrdenPagoDAO.class),c);assertNull(s.convertir(orden("http://inseguro.test",LocalDateTime.of(2026,10,14,10,10))).checkoutUrl());assertNull(s.convertir(orden("https://seguro.test",LocalDateTime.of(2026,10,14,9,59))).checkoutUrl());}}
